```cpp
// MeuJogo.h (header do módulo)
#pragma once
#include "CoreMinimal.h"

DECLARE_LOG_CATEGORY_EXTERN(LogMeuJogo, Log, All);
```

```cpp
// MeuJogo.cpp
#include "MeuJogo.h"
