Quem causa o dano chama `UGameplayStatics::ApplyDamage`:

```cpp
UGameplayStatics::ApplyDamage(Alvo, 25.f, GetInstigatorController(), this, UDamageType::StaticClass());

// dano em área com queda pela distância
UGameplayStatics::ApplyRadialDamage(GetWorld(), 80.f, GetActorLocation(), 400.f,
    UDamageType::StaticClass(), TArray<AActor*>{ this }, this, GetInstigatorController(), true);
