#include "BTTask_Atacar.h"
#include "AIController.h"
#include "BehaviorTree/BlackboardComponent.h"
#include "Inimigo.h"

UBTTask_Atacar::UBTTask_Atacar()
{
    NodeName = TEXT("Atacar");
    ChaveAlvo.AddObjectFilter(this, GET_MEMBER_NAME_CHECKED(UBTTask_Atacar, ChaveAlvo), AActor::StaticClass());
}

EBTNodeResult::Type UBTTask_Atacar::ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory)
{
    AAIController* Controller = OwnerComp.GetAIOwner();
    AInimigo* Inimigo = Controller ? Cast<AInimigo>(Controller->GetPawn()) : nullptr;
    AActor* Alvo = Cast<AActor>(OwnerComp.GetBlackboardComponent()->GetValueAsObject(ChaveAlvo.SelectedKeyName));

    if (!Inimigo || !Alvo) return EBTNodeResult::Failed;

    Inimigo->Atacar(Alvo);
    return EBTNodeResult::Succeeded;
}
```

