    ConfigVisao->SightRadius = 1500.f;
    ConfigVisao->LoseSightRadius = 1800.f;
    ConfigVisao->PeripheralVisionAngleDegrees = 70.f;
    ConfigVisao->DetectionByAffiliation.bDetectEnemies = true;
    ConfigVisao->DetectionByAffiliation.bDetectNeutrals = true;
    ConfigVisao->DetectionByAffiliation.bDetectFriendlies = false;

    Percepcao->ConfigureSense(*ConfigVisao);
    Percepcao->SetDominantSense(ConfigVisao->GetSenseImplementation());
}

