```cpp
// GA_Dash.cpp
#include "GA_Dash.h"
#include "GameFramework/Character.h"

UGA_Dash::UGA_Dash()
{
    InstancingPolicy = EGameplayAbilityInstancingPolicy::InstancedPerActor;
    NetExecutionPolicy = EGameplayAbilityNetExecutionPolicy::LocalPredicted;
}

void UGA_Dash::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo,
                               const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
{
    if (!CommitAbility(Handle, ActorInfo, ActivationInfo)) // aplica custo e cooldown
    {
        EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
        return;
    }

    if (ACharacter* Personagem = Cast<ACharacter>(ActorInfo->AvatarActor.Get()))
    {
        Personagem->LaunchCharacter(Personagem->GetActorForwardVector() * Forca, true, false);
    }

    EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
}
```

O custo e o cooldown são Gameplay Effects configurados no Blueprint da habilidade (`Cost Gameplay Effect Class` e `Cooldown Gameplay Effect Class`). Ative com `ASC->TryActivateAbilityByClass(UGA_Dash::StaticClass())` ou por tag.

```cpp
#include "AbilitySystemComponent.h"
#include "AbilitySystemBlueprintLibrary.h"

UPROPERTY(EditDefaultsOnly, Category="GAS")
TSubclassOf<UGameplayEffect> EfeitoDano;

void AArmadilha::AplicarEm(AActor* Alvo)
{
    UAbilitySystemComponent* ASCAlvo = UAbilitySystemBlueprintLibrary::GetAbilitySystemComponent(Alvo);
    if (!ASCAlvo || !EfeitoDano) return;

    FGameplayEffectContextHandle Contexto = ASCAlvo->MakeEffectContext();
    Contexto.AddSourceObject(this);

    const FGameplayEffectSpecHandle Spec = ASCAlvo->MakeOutgoingSpec(EfeitoDano, 1.f, Contexto);
    if (Spec.IsValid())
    {
        // valor definido em tempo de execução (o efeito usa "Set By Caller" com esta tag)
        Spec.Data->SetSetByCallerMagnitude(FGameplayTag::RequestGameplayTag(TEXT("Dados.Dano")), -25.f);
        ASCAlvo->ApplyGameplayEffectSpecToSelf(*Spec.Data.Get());
    }
}
```

O Gameplay Effect (criado como Blueprint) define qual atributo muda (ex.: `Vida`), a operação (Add) e a duração (Instant, Has Duration, Infinite). Aplique efeitos no servidor.

Gameplay Tags são rótulos hierárquicos (`Estado.Atordoado`, `Arma.Espada`) definidos no projeto, mais seguros e rápidos que strings.

```cpp
