// PortaAutomatica.cpp
#include "PortaAutomatica.h"
#include "Components/BoxComponent.h"
#include "GameFramework/Character.h"

APortaAutomatica::APortaAutomatica()
{
    PrimaryActorTick.bCanEverTick = true;
    Raiz = CreateDefaultSubobject<USceneComponent>(TEXT("Raiz"));
    RootComponent = Raiz;
    Porta = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Porta"));
    Porta->SetupAttachment(Raiz);
    Area = CreateDefaultSubobject<UBoxComponent>(TEXT("Area"));
    Area->SetupAttachment(Raiz);
    Area->SetBoxExtent(FVector(150.f, 150.f, 100.f));
    Area->SetCollisionProfileName(TEXT("Trigger"));
}

void APortaAutomatica::BeginPlay()
{
    Super::BeginPlay();
    if (CurvaAbertura)
    {
        FOnTimelineFloat Progresso;
        Progresso.BindUFunction(this, FName(TEXT("AtualizarAbertura")));
        Timeline.AddInterpFloat(CurvaAbertura, Progresso);
    }
    Area->OnComponentBeginOverlap.AddDynamic(this, &APortaAutomatica::AoEntrar);
    Area->OnComponentEndOverlap.AddDynamic(this, &APortaAutomatica::AoSair);
}

void APortaAutomatica::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);
    Timeline.TickTimeline(DeltaTime);
}

void APortaAutomatica::AtualizarAbertura(float Alpha)
{
    Porta->SetRelativeRotation(FRotator(0.f, AnguloAberta * Alpha, 0.f));
}

void APortaAutomatica::AoEntrar(UPrimitiveComponent*, AActor* Outro, UPrimitiveComponent*, int32, bool, const FHitResult&)
{
    if (Cast<ACharacter>(Outro)) Timeline.Play();
}

void APortaAutomatica::AoSair(UPrimitiveComponent*, AActor* Outro, UPrimitiveComponent*, int32)
{
    if (Cast<ACharacter>(Outro)) Timeline.Reverse();
}
