    UPROPERTY(EditDefaultsOnly, Category="Arma") int32 TamanhoPente = 30;
    UPROPERTY(EditDefaultsOnly, Category="Arma") int32 Reserva = 90;
    UPROPERTY(EditDefaultsOnly, Category="Arma") float TirosPorMinuto = 600.f;
    UPROPERTY(EditDefaultsOnly, Category="Arma") float TempoRecarga = 2.f;
    UPROPERTY(EditDefaultsOnly, Category="Arma") float Dano = 20.f;
    UPROPERTY(EditDefaultsOnly, Category="Arma") float Alcance = 10000.f;

private:
    int32 NoPente = 0;
    bool bRecarregando = false;
    float UltimoTiro = -1000.f;
