```cpp
// Arma.cpp
#include "Arma.h"
#include "Kismet/GameplayStatics.h"

AArma::AArma()
{
    PrimaryActorTick.bCanEverTick = false;
    Malha = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("Malha"));
    RootComponent = Malha;
}

void AArma::BeginPlay()
{
    Super::BeginPlay();
    NoPente = TamanhoPente;
}

void AArma::ComecarAtirar()
{
    const float Intervalo = 60.f / TirosPorMinuto;
    // respeita a cadência mesmo clicando rápido
    const float Espera = FMath::Max(UltimoTiro + Intervalo - GetWorld()->GetTimeSeconds(), 0.f);
    GetWorldTimerManager().SetTimer(TimerTiro, this, &AArma::Atirar, Intervalo, true, Espera);
}

void AArma::PararAtirar()
{
    GetWorldTimerManager().ClearTimer(TimerTiro);
}

void AArma::Atirar()
{
    if (bRecarregando) return;
    if (NoPente <= 0) { PararAtirar(); Recarregar(); return; }

    --NoPente;
    UltimoTiro = GetWorld()->GetTimeSeconds();
    AoMudarMunicao.Broadcast(NoPente, Reserva);

    APawn* Dono = Cast<APawn>(GetOwner());
    if (!Dono || !Dono->GetController()) return;

    FVector Inicio; FRotator Rot;
    Dono->GetController()->GetPlayerViewPoint(Inicio, Rot);
    const FVector Fim = Inicio + Rot.Vector() * Alcance;

    FHitResult Hit;
    FCollisionQueryParams Params(SCENE_QUERY_STAT(TiroArma), true, this);
    Params.AddIgnoredActor(Dono);
    if (GetWorld()->LineTraceSingleByChannel(Hit, Inicio, Fim, ECC_Visibility, Params))
    {
        UGameplayStatics::ApplyPointDamage(Hit.GetActor(), Dano, Rot.Vector(), Hit, Dono->GetController(), this, nullptr);
    }
}

void AArma::Recarregar()
{
    if (bRecarregando || NoPente == TamanhoPente || Reserva <= 0) return;
    bRecarregando = true;
    PararAtirar();
    GetWorldTimerManager().SetTimer(TimerRecarga, this, &AArma::TerminarRecarga, TempoRecarga, false);
}

void AArma::TerminarRecarga()
{
    const int32 Falta = TamanhoPente - NoPente;
    const int32 Repor = FMath::Min(Falta, Reserva);
    NoPente += Repor;
    Reserva -= Repor;
    bRecarregando = false;
    AoMudarMunicao.Broadcast(NoPente, Reserva);
}
```

O personagem chama `ComecarAtirar` no `Started` e `PararAtirar` no `Completed` da Input Action de tiro. Em multijogador, o disparo real deve ir por um RPC `Server`.

