```cpp
// SpawnerOndas.cpp
#include "SpawnerOndas.h"
#include "Inimigo.h"

void ASpawnerOndas::IniciarProximaOnda()
{
    if (!HasAuthority() || !Ondas.IsValidIndex(OndaAtual + 1) || PontosSpawn.Num() == 0) return;
    ++OndaAtual;
    RestantesParaSpawnar = Ondas[OndaAtual].Quantidade;
    GetWorldTimerManager().SetTimer(TimerSpawn, this, &ASpawnerOndas::SpawnarUm, Ondas[OndaAtual].IntervaloSpawn, true, 0.f);
}

void ASpawnerOndas::SpawnarUm()
{
    if (RestantesParaSpawnar <= 0) { GetWorldTimerManager().ClearTimer(TimerSpawn); return; }

    AActor* Ponto = PontosSpawn[FMath::RandRange(0, PontosSpawn.Num() - 1)];
    FActorSpawnParameters Params;
    Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;

    if (AInimigo* Inimigo = GetWorld()->SpawnActor<AInimigo>(Ondas[OndaAtual].Classe, Ponto->GetActorTransform(), Params))
    {
        Inimigo->OnDestroyed.AddDynamic(this, &ASpawnerOndas::AoInimigoMorrer);
        ++Vivos;
    }
    --RestantesParaSpawnar;
}

void ASpawnerOndas::AoInimigoMorrer(AActor*)
{
    --Vivos;
    if (Vivos <= 0 && RestantesParaSpawnar <= 0)
    {
        GetWorldTimerManager().SetTimer(TimerPausa, this, &ASpawnerOndas::IniciarProximaOnda, PausaEntreOndas, false);
    }
}
```

