```cpp
// MeuPersonagem.cpp
#include "GameFramework/CharacterMovementComponent.h"

void AMeuPersonagem::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);

    const bool bMovendo = GetVelocity().SizeSquared2D() > 10.f;
    const bool bCorrendo = bQuerCorrer && bMovendo && Stamina > 0.f && !GetCharacterMovement()->IsFalling();

    if (bCorrendo)
    {
        Stamina = FMath::Max(0.f, Stamina - GastoPorSegundo * DeltaTime);
    }
    else
    {
        Stamina = FMath::Min(StaminaMaxima, Stamina + RecuperacaoPorSegundo * DeltaTime);
    }

    GetCharacterMovement()->MaxWalkSpeed = bCorrendo ? VelocidadeCorrer : VelocidadeAndar;
}
```

Ligue `ComecarCorrer` ao `Started` e `PararCorrer` ao `Completed` da Input Action de correr. Em multijogador, a velocidade precisa ser definida também no servidor (via RPC ou com um `UCharacterMovementComponent` personalizado), senão o servidor corrige a posição e o personagem "engasga".

```cpp
float AMeuPersonagem::TakeDamage(float DamageAmount, const FDamageEvent& DamageEvent, AController* EventInstigator, AActor* DamageCauser)
{
    if (bMorto) return 0.f;

    const float Aplicado = Super::TakeDamage(DamageAmount, DamageEvent, EventInstigator, DamageCauser);
    Vida = FMath::Clamp(Vida - Aplicado, 0.f, VidaMaxima);

    if (Vida <= 0.f)
    {
        Morrer();
    }
    return Aplicado;
}

void AMeuPersonagem::Morrer()
{
    bMorto = true;

    // para de receber input e de se mover
    if (APlayerController* PC = Cast<APlayerController>(GetController()))
    {
        DisableInput(PC);
    }
    GetCharacterMovement()->DisableMovement();

    // cápsula sem colisão e malha em ragdoll
    GetCapsuleComponent()->SetCollisionEnabled(ECollisionEnabled::NoCollision);
    GetMesh()->SetCollisionProfileName(TEXT("Ragdoll"));
    GetMesh()->SetSimulatePhysics(true);

    SetLifeSpan(10.f); // remove o corpo depois de 10 s
}
```

A malha esquelética precisa de um **Physics Asset** para o ragdoll funcionar. Em multijogador, decida a morte no servidor e use um `OnRep` (ex.: `OnRep_Morto`) para ativar o ragdoll nos clientes.

```cpp
void AInimigo::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);

    APawn* Jogador = UGameplayStatics::GetPlayerPawn(this, 0);
    if (!Jogador) return;

    FVector Direcao = Jogador->GetActorLocation() - GetActorLocation();
    Direcao.Z = 0.f; // gira só no plano horizontal (yaw)

    if (!Direcao.IsNearlyZero())
    {
        const FRotator Alvo = Direcao.Rotation();
        const FRotator Suave = FMath::RInterpTo(GetActorRotation(), Alvo, DeltaTime, 5.f);
        SetActorRotation(Suave);
    }
}
```

Se o inimigo usa um `AAIController`, prefira `AIController->SetFocus(Jogador);`: a IA gira o Pawn sozinha (com `bUseControllerRotationYaw = true` no Pawn, ou `bOrientRotationToMovement = false` e `bUseControllerDesiredRotation = true` no CharacterMovement).

