// InventarioComponent.cpp
#include "InventarioComponent.h"

bool UInventarioComponent::Adicionar(FName Item, int32 Qtd)
{
    if (Item.IsNone() || Qtd <= 0) return false;
    if (!Itens.Contains(Item) && Itens.Num() >= EspacosMaximos) return false; // sem espaço

    Itens.FindOrAdd(Item) += Qtd;
    AoMudar.Broadcast();
    return true;
}

bool UInventarioComponent::Remover(FName Item, int32 Qtd)
{
    int32* Atual = Itens.Find(Item);
    if (!Atual || *Atual < Qtd) return false;

    *Atual -= Qtd;
    if (*Atual == 0) Itens.Remove(Item);
    AoMudar.Broadcast();
    return true;
}
