void AMeuAtor::AdicionarLuz()
{
    UPointLightComponent* NovaLuz = NewObject<UPointLightComponent>(this, TEXT("LuzDinamica"));
    NovaLuz->SetupAttachment(RootComponent); // antes de registrar ainda é permitido
    NovaLuz->RegisterComponent();
    NovaLuz->SetIntensity(5000.f);
    AddInstanceComponent(NovaLuz); // aparece no painel Details
    Luz = NovaLuz;
}
